// Typed wrappers around Tauri commands. One function per command, importing payload types only from
// src/bindings/ (generated by ts-rs, never hand-edited). See docs/ARCHITECTURE.md §6 and D-012.
import { invoke, isTauri } from "@tauri-apps/api/core";
import type { AppInfo } from "@/bindings/AppInfo";
import type { LunaError } from "@/bindings/LunaError";

/** Thrown by every IPC call. Carries the backend's typed error so the UI can map `code` to text. */
export class IpcError extends Error {
  readonly error: LunaError;

  constructor(error: LunaError) {
    super(error.message);
    this.name = "IpcError";
    this.error = error;
  }
}

export function isLunaError(value: unknown): value is LunaError {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return typeof candidate.code === "string" && typeof candidate.message === "string";
}

/** Anything a failed `invoke` can reject with, as a `LunaError`. */
export function toLunaError(thrown: unknown): LunaError {
  if (isLunaError(thrown)) return thrown;
  const message = thrown instanceof Error ? thrown.message : String(thrown);
  return { code: "INTERNAL", message };
}

async function call<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  if (!isTauri()) {
    // `pnpm dev` in a plain browser has no backend. Say so instead of failing obscurely.
    throw new IpcError({
      code: "INTERNAL",
      message: "The lunaRun backend is not available. Open the desktop app to use this feature.",
    });
  }
  try {
    return await invoke<T>(command, args);
  } catch (thrown) {
    throw new IpcError(toLunaError(thrown));
  }
}

export const ipc = {
  appInfo: () => call<AppInfo>("app_info"),
} as const;
